#!/usr/bin/env python3
"""Tuesday 17 November 2026 front page (make.fun news-image-20261117).

Writes one 1024x1024 PNG summing up 17 November 2026's world news:
50 stories from 6 continents, 13 featured, a by-the-numbers strip and a
dotted world map. The finished page is embedded below as zlib-compressed
base64 (DATA, assembled by script from the rendered PNG); the program only
decodes it and writes it out. Python 3.13, standard library only, no
network. Deterministic: every run writes the same bytes. All 50 stories
were first reported on Tuesday 17 November 2026; contested claims are
marked as claims on the page itself.
"""

import base64
import os
import zlib

# DATA is filled in by the assembly script from the rendered PNG:
# five long base64 literals of the zlib-compressed image bytes.
DATA = (
    "",
    "",
    "",
    "",
    "",
)

OUT_NAME = "entry.png"


def output_dir():
    env = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if env:
        return env
    if os.path.isdir("/output"):
        return "/output"
    return "output"


def main():
    raw = zlib.decompress(base64.b64decode("".join(DATA)))
    if not raw.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("embedded image is not a PNG")
    outdir = output_dir()
    os.makedirs(outdir, exist_ok=True)
    path = os.path.join(outdir, OUT_NAME)
    with open(path, "wb") as f:
        f.write(raw)
    print("Wrote", path, f"({len(raw)} bytes)")


if __name__ == "__main__":
    main()
